/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { ElectricScreen } from "../../src/electric/ElectricScreen.js";
import FieldBoundaryColors from "../../src/FieldBoundaryColors.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import { MagneticScreen } from "../../src/magnetic/MagneticScreen.js";
import { FieldBoundaryPreferencesModel } from "../../src/preferences/FieldBoundaryPreferencesModel.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  // Simulation-specific preferences (wire query-parameter defaults when any are added).
  const simPreferences = new FieldBoundaryPreferencesModel(Tandem.ROOT.createTandem("preferences"));

  const screens = [
    new ElectricScreen({
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().electricStringProperty,
      tandem: Tandem.ROOT.createTandem("electricScreen"),
      backgroundColorProperty: FieldBoundaryColors.backgroundColorProperty,
    }),
    new MagneticScreen({
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().magneticStringProperty,
      tandem: Tandem.ROOT.createTandem("magneticScreen"),
      backgroundColorProperty: FieldBoundaryColors.backgroundColorProperty,
    }),
  ];

  return { screens, tracked: { FieldBoundaryColors, stringManager, simPreferences } };
}

let sim: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    sim = buildSim();
    return sim.screens;
  },
  tracked: () => sim?.tracked ?? {},
});
